    };
  if (land === "CH") {
    const ch = uebersetze({ de: ENERGIEGEMEINSCHAFTEN_CH.metadata, en: ENERGIEGEMEINSCHAFTEN_CH_EN.metadata }, "en");
    return { ...basis, ...ch, openGraph: { ...basis.openGraph, ...ch.openGraph } };
  }
  return basis;
};
const metadataFuer = (land, p) =>
  p?.sprache === "en"
    ? metadataFuerEn(land)
    : land === "AT"
    ? {
        ...metadata,
        title: "Energiegemeinschaft in Österreich gründen & versorgen (EEG, BEG) | ÖkoInvest",
        description: "Erneuerbare-Energie-Gemeinschaft oder Bürgerenergiegemeinschaft in Österreich gründen oder mit Parkstrom versorgen – mit Vergleich zu Energy Sharing in Deutschland und LEG in der Schweiz.",
      }
    : land === "CH"
      ? { ...metadata, ...ENERGIEGEMEINSCHAFTEN_CH.metadata, openGraph: { ...metadata.openGraph, ...ENERGIEGEMEINSCHAFTEN_CH.metadata.openGraph } }
      : metadata;

const META_EN = {
  title: "Solar parks, agri-PV & project exchange DACH | ÖkoInvest",
  description:
    "Lease your land, implement agrivoltaics, buy or sell PV projects: ÖkoInvest develops solar parks in DE, AT and CH. Check your land free of charge now.",
};

const metadata = {
  title: META.title,
  description: META.description,
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs("/"),
    siteName: "ÖkoInvest",
    title: META.title,
    description: META.description,
    images: [{ url: abs("/img/solarpark-himmel.jpg"), width: 1280, height: 852, alt: "Solarpark unter blauem Himmel" }],
  },
};

const metadataEn = {
  title: META_EN.title,
  description: META_EN.description,
  openGraph: { title: META_EN.title, description: META_EN.description, images: [{ alt: "Solar park under a blue sky" }] },
};

input.command:
cd ~/claude-browser && MSYS_NO_PATHCONV=1 node -e '
const basis = "http://localhost:3100";
const pfade = ["/","/flaeche-verpachten","/dachflaeche-verpachten","/agri-pv","/freiflaeche","/solarcarport","/grossspeicher","/virtuelles-kraftwerk","/bestandsanlagen","/investoren","/projektboerse","/landwirte","/kommunen","/energiegemeinschaften","/gebaeudestrom","/parkplatz","/reststrom","/flaechencheck","/rechner","/marktdaten","/ratgeber","/faq","/regionen","/unternehmen","/warum-oekoinvest","/prozess","/kontakt","/referenzen","/genossenschaft","/newsletter","/newsroom","/quellen","/energie-live","/wissen/lexikon","/rechner/pacht","/rechner/flaechenpass","/rechner/gewerbestrom-check","/rechner/gebaeudestrom","/en","/ch/freiflaeche"];
const ent = (s)=>s.replace(/&amp;/g,"&").replace(/&#x27;|&apos;/g,"’");
for (const p of pfade) {
  let h; for (let v=0;v<4;v++){ try { h = await (await fetch(basis+p,{signal:AbortSignal.timeout(120000),headers:{connection:"close"}})).text(); break;} catch(e){ await new Promise(r=>setTimeout(r,4000)); } }
  if (!h){ console.log("?? "+p+" keine Antwort"); continue; }
  const t = ent((h.match(/<title>([^<]*)<\/title>(?:<meta[^>]*>)*?<meta name="description"/)||h.match(/<title>([^<]*\|[^<]*)<\/title>/)||[])[1]||"");
  const d = ent((h.match(/<meta name="description" content="([^"]*)"/)||[])[1]||"");
  const warn = [];
  if (t.length>60) warn.push("TITLE "+t.length);
  if (d.length>160) warn.push("DESC "+d.length);
  if (d.length<120 && d) warn.push("desc kurz "+d.length);
  console.log((warn.length?"!! ":"OK ")+p.padEnd(32)+" t="+String(t.length).padStart(2)+" d="+String(d.length).padStart(3)+(warn.length?"  "+warn.join(", "):""));
}' 2>&1

